# Get ChatClientAgent details
cd /tmp/probe && cat > Program.cs << 'CSHARP'
using System.Reflection;

var asm = Assembly.LoadFrom("Microsoft.Agents.AI.dll");

void DumpType(string name) {
    var t = asm.GetExportedTypes().FirstOrDefault(t => t.Name == name);
    if (t == null) { Console.WriteLine($"Type {name} not found"); return; }
    Console.WriteLine($"\n=== {t.FullName} ===");
    foreach (var c in t.GetConstructors(BindingFlags.Public | BindingFlags.Instance))
        Console.WriteLine($"  ctor({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
    foreach (var m in t.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
        Console.WriteLine($"  {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
    foreach (var p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
        Console.WriteLine($"  prop {p.PropertyType.Name} {p.Name}");
}

DumpType("ChatClientAgent");
DumpType("ChatClientAgentOptions");
DumpType("ChatClientAgentRunOptions");
DumpType("AIAgentBuilder");
DumpType("AIAgentExtensions");
CSHARP
dotnet run 2>&1

