using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tools ---
var notebook = new ResearchNotebook();
var tools = new AIFunction[]
{
    AIFunctionFactory.Create(
        (string query) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Search the web for information on a topic. Returns a list of result snippets."),

    AIFunctionFactory.Create(
        ([Description("A concise heading for this note")] string title,
         [Description("The content to save")] string content) =>
        {
            notebook.AddNote(title, content);
            return $"Note saved: \"{title}\"";
        },
        "save_note",
        "Save a research note. Use this to record important findings as you research."),

    AIFunctionFactory.Create(
        () => notebook.GetAllNotes(),
        "get_notes",
        "Retrieve all notes saved so far."),
};

// --- Build the agent ---
var openAiClient = new OpenAIClient(apiKey);

IChatClient chatClient = openAiClient.GetChatClient(modelId).AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic you must:
        1. Use web_search to find relevant information (make several varied searches).
        2. Use save_note to record key findings as you go.
        3. After gathering enough information, use get_notes to review everything.
        4. Provide a well-structured summary with sections and source references.
        Be thorough — search at least 3 different queries before summarizing.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking.",
    tools: tools);

// --- Run ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine(new string('─', 50));

var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions);

Console.WriteLine();
Console.WriteLine(response.Text);

Console.WriteLine();
Console.WriteLine(new string('─', 50));
Console.WriteLine($"Research complete. {notebook.Count} note(s) collected.");

if (response.Usage is { } usage)
{
    Console.WriteLine($"Tokens — input: {usage.InputTokenCount}, output: {usage.OutputTokenCount}");
}

