// Tool implementations
// ============================================================

/// <summary>Simulates web search using a simple HTTP request.</summary>
static class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
    };

    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            // Use DuckDuckGo lite (HTML) which doesn't require an API key
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
            var html = await s_http.GetStringAsync(url);

            var results = ParseResults(html);
            if (results.Count == 0)
                return $"No results found for: {query}";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: {query}");
            sb.AppendLine();
            foreach (var (title, snippet, link) in results.Take(5))
            {
                sb.AppendLine($"• {title}");
                if (!string.IsNullOrEmpty(snippet))
                    sb.AppendLine($"  {snippet}");
                if (!string.IsNullOrEmpty(link))
                    sb.AppendLine($"  Source: {link}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }

    private static List<(string Title, string Snippet, string Link)> ParseResults(string html)
    {
        var results = new List<(string, string, string)>();

        // Simple parsing of DuckDuckGo lite results
        var lines = html.Split('\n');
        string? currentTitle = null;
        string? currentLink = null;
        string? currentSnippet = null;

        foreach (var rawLine in lines)
        {
            var line = rawLine.Trim();

            // Links with result class
            if (line.Contains("class=\"result-link\"") || line.Contains("class='result-link'"))
            {
                currentTitle = StripHtml(line);
                var hrefIdx = line.IndexOf("href=\"", StringComparison.OrdinalIgnoreCase);
                if (hrefIdx >= 0)
                {
                    hrefIdx += 6;
                    var endIdx = line.IndexOf('"', hrefIdx);
                    if (endIdx > hrefIdx)
                        currentLink = line[hrefIdx..endIdx];
                }
            }
            else if (line.Contains("class=\"result-snippet\"") || line.Contains("class='result-snippet'"))
            {
                currentSnippet = StripHtml(line);
                if (currentTitle is not null)
                {
                    results.Add((currentTitle, currentSnippet ?? "", currentLink ?? ""));
                    currentTitle = null;
                    currentLink = null;
                    currentSnippet = null;
                }
            }
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        var sb = new StringBuilder();
        var inTag = false;
        foreach (var c in html)
        {
            if (c == '<') inTag = true;
            else if (c == '>') inTag = false;
            else if (!inTag) sb.Append(c);
        }

        return System.Net.WebUtility.HtmlDecode(sb.ToString().Trim());
    }
}

/// <summary>Thread-safe notebook for collecting research findings.</summary>
sealed class ResearchNotebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];
    private readonly Lock _lock = new();

    public int Count
    {
        get { lock (_lock) return _notes.Count; }
    }

    public void AddNote(string title, string content)
    {
        lock (_lock)
        {
            _notes.Add((title, content, DateTime.UtcNow));
        }
    }

    public string GetAllNotes()
    {
        lock (_lock)
        {
            if (_notes.Count == 0)
                return "No notes saved yet.";

            var sb = new StringBuilder();
            sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===");
            sb.AppendLine();
            for (var i = 0; i < _notes.Count; i++)
            {
                var (title, content, ts) = _notes[i];
                sb.AppendLine($"[{i + 1}] {title} ({ts:HH:mm:ss UTC})");
                sb.AppendLine(content);
                sb.AppendLine();
            }

            return sb.ToString();
        }
    }
}

